import axios from 'axios';

const API_BASE_URL = 'http://165.227.119.71/api/v1';

export const apiClient = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Add request interceptor to include auth token
apiClient.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('access_token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => Promise.reject(error)
);

// Add response interceptor to handle token refresh
apiClient.interceptors.response.use(
  (response) => response,
  async (error) => {
    if (error.response?.status === 401) {
      // Handle token refresh or logout
      localStorage.removeItem('access_token');
      window.location.href = '/login';
    }
    return Promise.reject(error);
  }
);

// API Endpoints
export const endpoints = {
  // Auth
  auth: {
    login: '/auth/login',
    refresh: '/auth/refresh',
    logout: '/auth/logout',
  },
  
  // Branches
  branches: '/branches',
  branch: (id: string) => `/branches/${id}`,
  branchStock: (id: string) => `/stock/branch/${id}`,
  
  // Products
  products: '/products',
  product: (id: string) => `/products/${id}`,
  productStock: (id: string) => `/stock/product/${id}`,
  
  // Stock
  stock: {
    initialize: '/stock/initialize',
    adjust: '/stock/adjust',
    lowStock: '/stock/low-stock',
    outOfStock: '/stock/out-of-stock',
  },
  
  // Transfers
  transfers: '/transfers',
  transfer: (id: string) => `/transfers/${id}`,
  transferDispatch: (id: string) => `/transfers/${id}/dispatch`,
  transferReceive: (id: string) => `/transfers/${id}/receive`,
  transferCancel: (id: string) => `/transfers/${id}/cancel`,
  
  // Sales
  sales: '/sales',
  sale: (id: string) => `/sales/${id}`,
  saleReturn: (id: string) => `/sales/${id}/return`,
  saleByReceipt: (no: string) => `/sales/receipt/${no}`,
  
  // Dashboard
  dashboard: {
    summary: '/dashboard/summary',
    alerts: '/dashboard/alerts',
    topProducts: '/dashboard/top-products',
    branches: '/dashboard/branch-comparison',
  },
  
  // Reports
  reports: {
    stockSnapshot: '/reports/stock-snapshot',
    lowStock: '/reports/low-stock',
  },
  
  // Users
  users: '/users',
  user: (id: string) => `/users/${id}`,
};

export default apiClient;
